from pathlib import Path
import json
fields=[
('幾何與施工','H','開挖深度 H','m',3,'從原地面量至本階段開挖面。','施工剖面圖／分階開挖計畫'),
('幾何與施工','q','地表均佈超載 q','tf/m²',1,'填地表面載重，不是水平線載重；原程式部分標示 t/m，已修正。','施工堆載計畫、車輛／機具換算、鄰房基礎評估'),
('幾何與施工','length','實際總樁長','m',7,'原地面至樁尖；可用入土深度＝總樁長−H。','施工圖、採購長度、實際打設紀錄'),
('土壤參數','gamma','砂土水位以上單位重 γ','tf/m³',1.8,'填現地天然／濕單位重。砂土均質乾燥工況全深使用此值。','鑽探報告、土壤密度試驗'),
('土壤參數','gammaSat','砂土飽和單位重 γsat','tf/m³',1.8,'水位以下有效單位重 γ′＝γsat−1.0；與天然單位重分開輸入。','鑽探報告、飽和密度試驗'),
('土壤參數','phi','砂土有效摩擦角 φ′','°',30,'採有效應力排水參數；Rankine 假設水平地表、直立光滑牆。','排水三軸／直剪试驗；經確認的地工設計參數'),
('土壤參數','gammaClay','黏土總單位重 γc','tf/m³',1.9,'均質黏土總應力分析使用；混合土層不代替上覆砂土重量。','鑽探與單位重試驗'),
('土壤參數','su','不排水剪力強度 Su','tf/m²',3.5,'輸入 Su；不是 qu。若資料是無圍壓縮強度 qu，先以 Su＝qu/2 轉換。','不排水三軸、十字片剪、無圍壓縮試驗'),
('水位與地錨','water','兩側相同水位深度 h₁','m',1.5,'從原地面向下量；原檔水位模型假設牆兩側水位一致，淨水壓為零。','水位計觀測及施工水位控制計畫'),
('水位與地錨','anchor','地錨深度 a','m',0.6,'從原地面至單層錨定支點；原程式 h₃＝H−a。','地錨施工剖面、圍令位置'),
('水位與地錨','spacing','地錨水平間距 s','m',2,'將每米牆反力乘以水平間距，取得每支地錨水平力。','平面配置圖'),
('水位與地錨','angle','地錨向下傾角 θ','°',15,'相對水平線；軸力 T＝Tₕs/cosθ。','地錨施工詳圖'),
('斷面與檢核','S','斷面模數 Sx','cm³/m',2270,'必須是每米完整牆寬斷面模數；不可直接輸入單支 cm³。原檔 35 款斷面保留供選擇。','供應商截面表、實際型號與有效牆寬'),
('斷面與檢核','eta','有效斷面折減 η','—',1,'S有效＝ηSx，考慮接頭滑移、腐蝕與重複使用；1 代表未折減。','供應商資料、接頭傳力評估、檢測紀錄'),
('斷面與檢核','fb','採用彎曲容許應力 fb','kgf/cm²',1500,'原檔預設值保留；需依材質、斷面與設計規範確認。不得只因為選了型號就視為適用。','核定設計準則、鋼材證明、鋼結構容許應力檢核'),
('斷面與檢核','mult','入土加長倍率 α','—',1.3,'需求入土＝αD理論；原檔列 1.2～1.4。此值不等於任意工況的安全係數。','設計方法適用條件；基礎規範 7.5.3 解說'),
('斷面與檢核','fs','土壤強度安全係數 FS','—',1.5,'单層地錨依規範 8.8.1，以 Su/FS、tanφ/FS 計算支點以下側壓平衡；FS 至少 1.2。懸臂僅用於原黏土 Hlim 參考。','原檔設定／設計準則')]
Path('fields.json').write_text(json.dumps(fields,ensure_ascii=False),encoding='utf-8')
